                    "count": count,
                    "states": states,
                    "interval": interval,
                    "from": base["state"],
                    "to": current["state"],
                    "rank": rank,
                }
            )

    return {
        "schema": _COMPARE_MATRIX_SCHEMA,
        "reference": reference,
        "names": list(compare_names),
        "tolerance": first_tolerance,
