            raise ValueError(f"{where}.name must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate items name: {name!r}")
        seen_names.add(name)

        tolerance, layers, scenarios, data = _validate_converge_matrix(
            item["matrix"], where=f"{where}.matrix"
        )
        if not validated:
            first_tolerance = tolerance
            first_layers = layers
            first_scenarios = scenarios
        else:
            if tolerance != first_tolerance:
                raise ValueError(
                    "all items must share the same matrix tolerance, taken "
                    "from the first item"
                )
            if layers != first_layers:
                raise ValueError(
                    "all items must share the same matrix layers in the same "
                    "order, taken from the first item"
                )
            if scenarios != first_scenarios:
                raise ValueError(
                    "all items must share the same matrix scenarios in the "
                    "same order, taken from the first item"
                )

        names.append(name)
        validated.append({row["scenario"]: row for row in data})

    reference = names[0]
    compare_names = names[1:]
    reference_rows = validated[0]

    rows = []
    for name, lookup in zip(compare_names, validated[1:]):
        for scenario in first_scenarios:
            base = reference_rows[scenario]
            current = lookup[scenario]
            count = current["count"] - base["count"]
            states = [
                current["states"][state] - base["states"][state]
                for state in _CONVERGE_STATES
            ]
            base_interval = base["interval"]
            current_interval = current["interval"]
            if base_interval is None or current_interval is None:
                interval = None
            else:
                interval = [
                    _round_output(current_interval[0] - base_interval[0]),
                    _round_output(current_interval[1] - base_interval[1]),
                ]
            base_rank = base["rank"]
            current_rank = current["rank"]
            if base_rank is None or current_rank is None:
                rank = None
            else:
                rank = current_rank - base_rank
            rows.append(
                {
                    "name": name,
                    "scenario": scenario,
                    "count": count,
                    "states": states,
                    "interval": interval,
                    "from": base["state"],
                    "to": current["state"],
                    "rank": rank,
                }
            )

    return {
        "schema": _COMPARE_MATRIX_SCHEMA,
        "reference": reference,
        "names": list(compare_names),
        "tolerance": first_tolerance,
        "layers": list(first_layers),
        "scenarios": list(first_scenarios),
        "data": rows,
    }

